import math

def parse_grid(s):
    return [[int(x) for x in row.split()] for row in s.strip().split('\n')]

test = parse_grid(test_input_str)
rows, cols = len(test), len(test[0])

twos = [(y,x) for y in range(rows) for x in range(cols) if test[y][x] == 2]

print(f"Found {len(twos)} twos")

# Try various distances
for dist in [0.5, 1.0, 1.5, 2.0]:
    result = [row[:] for row in test]
    for ty, tx in twos:
        for y in range(rows):
            for x in range(cols):
                d = math.hypot(y-ty, x-tx)
                if test[y][x] == 0 and d <= dist:
                    result[y][x] = 8

    changes = sum(1 for y in range(rows) for x in range(cols) if result[y][x] == 8)
    print(f"\nDistance {dist}: {changes} total 8s")

