import math

def parse_grid(s):
    return [[int(x) for x in row.split()] for row in s.strip().split('\n')]

test = parse_grid(test_input_str)
rows, cols = len(test), len(test[0])

twos = [(y,x) for y in range(rows) for x in range(cols) if test[y][x] == 2]

c = sum(twos[0])
half_w = 5

result = [row[:] for row in test]
for y in range(rows):
    for x in range(cols):
        if test[y][x] == 0 and abs(x + y - c) <= half_w:
            result[y][x] = 8

changes = []
for y in range(rows):
    for x in range(cols):
        if result[y][x] == 8 and test[y][x] == 0:
            changes.append((y,x))

print("All 8s:")
by_row = {}
for chg in changes:
    by_row.setdefault(chg[0], []).append(chg[1])

for y in sorted(by_row.keys()):
    print(f"y={y}: {sorted(by_row[y])}")

print("\n=== Result grid ===")
for y in range(rows):
    print(' '.join(map(str, result[y])))

